/* Embedded Lottie template. Export never reads the user's Downloads directory.
 * Template bytes are immutable; each export gets a new images/img_0.png blob.
 * data.json and all other images are copied verbatim, without reserialization.
 */
(function(root) {
  'use strict';
  const entries = Object.freeze([{"path":"data.json","data":""},{"path":"images/img_1.png","data":""},{"path":"images/img_10.png","data":""},{"path":"images/img_11.png","data":""},{"path":"images/img_12.png","data":""},{"path":"images/img_13.png","data":""},{"path":"images/img_14.png","data":""},{"path":"images/img_15.png","data":""},{"path":"images/img_16.png","data":""},{"path":"images/img_17.png","data":""},{"path":"images/img_18.png","data":""},{"path":"images/img_19.png","data":""},{"path":"images/img_2.png","data":""},{"path":"images/img_20.png","data":""},{"path":"images/img_21.png","data":""},{"path":"images/img_22.png","data":""},{"path":"images/img_23.png","data":""},{"path":"images/img_24.png","data":""},{"path":"images/img_25.png","data":""},{"path":"images/img_26.png","data":""},{"path":"images/img_27.png","data":""},{"path":"images/img_28.png","data":""},{"path":"images/img_29.png","data":""},{"path":"images/img_3.png","data":""},{"path":"images/img_30.png","data":""},{"path":"images/img_31.png","data":""},{"path":"images/img_32.png","data":""},{"path":"images/img_33.png","data":""},{"path":"images/img_34.png","data":""},{"path":"images/img_35.png","data":""},{"path":"images/img_36.png","data":""},{"path":"images/img_37.png","data":""},{"path":"images/img_38.png","data":""},{"path":"images/img_39.png","data":""},{"path":"images/img_4.png","data":""},{"path":"images/img_40.png","data":""},{"path":"images/img_41.png","data":""},{"path":"images/img_5.png","data":""},{"path":"images/img_6.png","data":""},{"path":"images/img_7.png","data":""},{"path":"images/img_8.png","data":""},{"path":"images/img_9.png","data":""}].map(entry => Object.freeze(entry)));
  const replacementPath = 'images/img_0.png';
  const check = signal => { if (signal?.aborted) throw new DOMException('已取消导出', 'AbortError'); };
  function createFiles(detailImage, signal) {
    check(signal);
    if (!(detailImage instanceof Blob) || !detailImage.size || detailImage.type !== 'image/png') {
      throw new Error('Lottie 缺少有效的商详 PNG，无法打包。');
    }
    const files = entries.map(entry => {
      check(signal);
      const binary = atob(entry.data);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      return { name: 'Lottie/' + entry.path, blob: new Blob([bytes]) };
    });
    files.push({ name: 'Lottie/' + replacementPath, blob: detailImage });
    return files;
  }
  root.LottieBundle = Object.freeze({ createFiles, fileCount: entries.length + 1, replacementPath });
})(globalThis);
